const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const b=await chromium.launch(),p=await b.newPage({viewport:{width:390,height:844}});const out=[];const mark=(name,data)=>{out.push({name,data});console.log(name,JSON.stringify(data))};try{await p.goto('http://127.0.0.1:4183/ro/product/nuci-dracula-farm');await p.locator('.product-detail').waitFor();await p.keyboard.press('Tab');mark('first keyboard focus',await p.evaluate(()=>({tag:document.activeElement.tagName,text:document.activeElement.textContent,href:document.activeElement.getAttribute('href')})));await p.keyboard.press('Enter');mark('skip content target',await p.evaluate(()=>document.activeElement.id));await p.locator('[data-action=image]').click();mark('dialog',await p.locator('dialog').evaluate(e=>({open:e.open,label:e.getAttribute('aria-label'),labelledby:e.getAttribute('aria-labelledby'),role:e.getAttribute('role')})));await p.keyboard.press('Escape');mark('escape closes dialog',await p.locator('dialog').evaluate(e=>!e.open));await p.goto('http://127.0.0.1:4183/ro/collection');await p.locator('.filters').waitFor();mark('filter semantics',await p.locator('[data-action=filter]').evaluateAll(es=>es.map(e=>({text:e.textContent,pressed:e.getAttribute('aria-pressed'),selected:e.getAttribute('aria-selected')}))));await p.screenshot({path:'outputs/dracula-food/audit-mobile.png',fullPage:true});mark('missing label fields',await p.locator('input,select,textarea').evaluateAll(es=>es.filter(e=>!e.labels?.length&&!e.getAttribute('aria-label')&&!e.getAttribute('aria-labelledby')).map(e=>e.id)));}finally{fs.writeFileSync('work/audit-food-accessibility-results.json',JSON.stringify(out,null,2));await b.close()}})();
